func:
// ==== HIER DEINE ENDPUNKTE DEFINIEREN ====
// kind: "read" | "switch" | "number" | "action"
// invoke: {url, method} ODER {mqttTopic, mqttPayloadOn, mqttPayloadOff}
const endpoints = [
  {
    id: "pump",
    label: "Pumpe",
    kind: "switch",
    group: "Bewaesserung",
    voice: true,
    invoke: { mqttTopic: env.get("MQTT_COMMAND_TOPIC"), mqttPayloadOn: "ON", mqttPayloadOff: "OFF" },
  },
  { id: "pump_watts", label: "Leistung", kind: "read", unit: "W", group: "Bewaesserung" },
  { id: "outside_temp_c", label: "Aussentemperatur", kind: "read", unit: "°C", group: "Wetter" },
  { id: "pv_surplus_w", label: "PV-Ueberschuss", kind: "read", unit: "W", group: "Energie" },
];

msg.payload = { source: "node-red", replace: true, endpoints };
msg.headers = { "content-type": "application/json" };
if (env.get("PI_INGEST_TOKEN")) msg.headers.authorization = "Bearer " + env.get("PI_INGEST_TOKEN");
msg.url = env.get("LOCAL_ANNOUNCE_URL");
return msg;

// MQTT/Sensordaten -> Endpunkt-Werte. Topic auf Endpunkt-ID mappen.
const map = {
  "stat/zisterne/POWER": ["pump", (v) => String(v).toUpperCase() === "ON"],
  "tele/zisterne/SENSOR": ["pump_watts", (v) => { try { return JSON.parse(v).ENERGY.Power; } catch (e) { return null; } }],
  "sensor/outside/temp": ["outside_temp_c", (v) => Number(v)],
  "sensor/pv/surplus": ["pv_surplus_w", (v) => Number(v)],
};
const hit = map[msg.topic];
if (!hit) return null;
const value = hit[1](msg.payload);
if (value === null || value === undefined || Number.isNaN(value)) return null;

// max. 1 Update pro Endpunkt und 5 Sekunden
const key = "last_" + hit[0];
const last = flow.get(key) || 0;
if (Date.now() - last < 5000) return null;
flow.set(key, Date.now());

msg.payload = { values: { [hit[0]]: value }, source: "node-red" };
msg.headers = { "content-type": "application/json" };
if (env.get("PI_INGEST_TOKEN")) msg.headers.authorization = "Bearer " + env.get("PI_INGEST_TOKEN");
msg.url = env.get("LOCAL_ANNOUNCE_URL");
return msg;

// Pi Control ruft diesen Endpunkt: /pi-control/cmd?id=pump&value=true
const id = (msg.req && msg.req.query.id) || (msg.payload && msg.payload.id);
let value = (msg.req && msg.req.query.value);
if (value === undefined && msg.payload) value = msg.payload.value;
if (value === "true") value = true;
if (value === "false") value = false;
if (!id) { msg.statusCode = 400; msg.payload = { ok: false, error: "id fehlt" }; return [null, msg]; }

const on = value === true || value === "ON" || Number(value) > 0;
msg.topic = env.get("MQTT_COMMAND_TOPIC");
msg.payload = on ? "ON" : "OFF";
msg._res_payload = { ok: true, id, value, topic: msg.topic, sent: msg.payload };
return [msg, null];

const e = msg.error || {};
msg.payload = {
  component: "node-red",
  status: "error",
  message: String(e.message || "unbekannter Fehler"),
  metrics: { source: (e.source && e.source.name) || null },
};
msg.headers = { "content-type": "application/json" };
if (env.get("PI_INGEST_TOKEN")) msg.headers.authorization = "Bearer " + env.get("PI_INGEST_TOKEN");
msg.url = env.get("LOCAL_TRACE_URL");
return msg;
